import streamlit as st
import pandas as pd
import matplotlib.pyplot as plt
from pathlib import Path

st.set_page_config(
    page_title="ML Algorithm Comparison",
    page_icon="🤖",
    layout="wide"
)

st.title("🤖 Machine Learning Algorithm Comparison")
st.write(
    "An interactive dashboard to explore classification, "
    "regression, and clustering results."
)

st.info(
    "This dashboard displays the results generated by your existing "
    "ML-Algorithm-Comparison project."
)

results_dir = Path("results")

st.sidebar.header("Navigation")
section = st.sidebar.selectbox(
    "Choose a section",
    ["Overview", "Classification", "Regression", "Clustering"]
)

if section == "Overview":
    st.subheader("Project Overview")
    st.markdown("""
    - **Classification:** Compare classification algorithms.
    - **Regression:** Evaluate regression models.
    - **Clustering:** Explore customer clusters.
    - **Evaluation:** Review model metrics and visualizations.
    """)

    result_file = results_dir / "model_comparison.csv"
    if result_file.exists():
        df = pd.read_csv(result_file)
        st.subheader("Model Comparison Results")
        st.dataframe(df, use_container_width=True)
    else:
        st.warning("The results/model_comparison.csv file was not found.")

elif section == "Classification":
    st.subheader("Classification Results")
    result_file = results_dir / "model_comparison.csv"

    if result_file.exists():
        df = pd.read_csv(result_file)
        st.dataframe(df, use_container_width=True)

        plot_file = results_dir / "classification_accuracy.png"
        if plot_file.exists():
            st.image(
                str(plot_file),
                caption="Classification Model Comparison",
                use_container_width=True
            )
    else:
        st.warning("Classification results are not available.")

elif section == "Regression":
    st.subheader("Regression Results")
    result_file = results_dir / "model_comparison.csv"

    if result_file.exists():
        df = pd.read_csv(result_file)
        st.dataframe(df, use_container_width=True)
    else:
        st.warning("Regression results are not available.")

elif section == "Clustering":
    st.subheader("Customer Clustering")
    cluster_file = results_dir / "customer_clusters.csv"

    if cluster_file.exists():
        df = pd.read_csv(cluster_file)
        st.dataframe(df.head(100), use_container_width=True)
        st.caption("Showing up to the first 100 customer records.")
    else:
        st.warning("The customer_clusters.csv file was not found.")

st.divider()
st.caption("Built with Python, Pandas, Matplotlib, and Streamlit.")
